parameters.jsCode:
// เตรียมข้อความตอบกลับ LINE + เก็บข้อมูลเชิงวิจัย (เวลาตอบสนอง, ผลการค้นความรู้)
const item = $input.first();
const receivedAt = Number($('Extract LINE Data').first().json.receivedAt) || Date.now();
const responseTimeMs = Math.max(Date.now() - receivedAt, 0);

// ข้อจำกัดจริงของ LINE Messaging API คือ 5,000 ตัวอักษร
// แต่ตั้งไว้ที่ 2,000 เพราะข้อความยาวกว่านี้ LINE จะซ่อนไว้หลังปุ่ม "ดูเพิ่มเติม"
// ซึ่งผู้ใช้ส่วนใหญ่ไม่กด เท่ากับข้อมูลส่วนนั้นสูญเปล่า
const MAX_LENGTH = 2000;
const FALLBACK =
  '⚠️ ขออภัยค่ะ ระบบขัดข้องชั่วคราว\nกรุณาลองพิมพ์คำถามใหม่อีกครั้งในอีกสักครู่นะคะ';

// ข้อความแจ้งข้อผิดพลาดไม่ต้องมีบรรทัดคำนวณจาก เพราะไม่มีการคำนวณเกิดขึ้น
function isErrorAnswerCandidate(text) {
  return !text || text === FALLBACK;
}

let answer = item.json.output || item.json.text || '';
if (item.json.error || !answer) {
  answer = FALLBACK;
}
answer = String(answer).trim();

// ---------------------------------------------------------------------------
// เติมบรรทัด "คำนวณจาก" ให้เองเมื่อแบบจำลองไม่ยกมา
// ---------------------------------------------------------------------------
// บรรทัดนี้บอกผู้ใช้ว่าระบบเข้าใจโจทย์ว่าอย่างไร สร้างจากค่าที่ส่งเข้าเครื่องคำนวณจริง
// มีสองหน้าที่
//   1. โจทย์ภาษาคนกำกวมได้ เช่น บุตรสอง หมายถึง บุตร 2 คน หรือ บุตรคนที่สอง
//      ถ้าระบบตีความผิดแล้วไม่บอก ผู้ใช้ไม่มีทางรู้
//   2. ถ้าแบบจำลองส่งค่าผิดช่อง ผู้ใช้เห็นทันที เช่นโจทย์บอกประกันชีวิต
//      แต่ระบบไปใส่ช่อง RMF ด้วย ซึ่งเดิมความผิดพลาดแบบนี้ซ่อนอยู่
//
// เคยลองสั่งในคำสั่งระบบให้ยกบรรทัดนี้มาแสดง แต่วัดจากการใช้งานจริงแล้วแบบจำลองไม่ทำตาม
// จึงย้ายมาบังคับด้วยโค้ด ตามหลักการเดิมของงานนี้
// ว่าสิ่งที่ต้องรับประกันได้ต้องบังคับด้วยกฎ ไม่ใช่ขอความร่วมมือ
//
// เขียนแบบไม่ให้พังถ้าโครงสร้างไม่ตรงที่คาด ถ้าหาไม่เจอก็ปล่อยคำตอบเดิมไว้
function findCalculationBasis(steps) {
  if (!Array.isArray(steps)) return '';
  for (const step of steps) {
    const raw = step && (step.observation ?? step.output ?? '');
    if (!raw) continue;
    try {
      const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
      if (parsed && parsed['คำนวณจาก']) return String(parsed['คำนวณจาก']);
    } catch (e) {
      // ผลจากเครื่องมือไม่ใช่ JSON ก็ข้ามไป ไม่ถือเป็นข้อผิดพลาด
    }
  }
  return '';
}

const calcBasis = findCalculationBasis(item.json.intermediateSteps);
if (calcBasis && !isErrorAnswerCandidate(answer)) {
  // เติมเฉพาะเมื่อยังไม่มีอยู่ในคำตอบ กันไม่ให้ซ้ำสองบรรทัด
  const alreadyThere = answer.indexOf('คำนวณจาก') >= 0;
  if (!alreadyThere) {
    answer = 'คำนวณจาก ' + calcBasis + '\n' + answer;
  }
}

// ---------------------------------------------------------------------------
// ด่านตรวจคำตอบผิดรูปแบบ
// ---------------------------------------------------------------------------
// แบบจำลองภาษาขนาดเล็กบางครั้ง "เขียน" คำสั่งเรียกเครื่องมือออกมาเป็นข้อความ
// แทนที่จะเรียกเครื่องมือจริง เช่นตอบว่า {"taxDue":10000,"monthsLate":3}
// ซึ่งเป็นข้อมูลนำเข้าของเครื่องมือ ไม่ใช่คำตอบที่ผู้ใช้ต้องการ
// ด่านนี้ตรวจจับแล้วเปลี่ยนเป็นข้อความที่เข้าใจได้ เพื่อไม่ให้ผู้ใช้เห็นข้อมูลดิบ
const looksLikeRawToolCall =
  /^[\s`]*[{[]/.test(answer) ||
  /^[\s`]*(json|tool_call|function_call)/i.test(answer);

if (looksLikeRawToolCall) {
  answer =
    'ขออภัยค่ะ ระบบประมวลผลคำถามนี้ไม่สมบูรณ์\n' +
    'รบกวนพิมพ์คำถามใหม่โดยระบุตัวเลขให้ชัดเจนอีกครั้งนะคะ\n\n' +
    'ตัวอย่างเช่น "ภาษีค้างชำระ 10,000 บาท ยื่นช้า 3 เดือน ต้องเสียเงินเพิ่มและค่าปรับเท่าไหร่"';
}
// ---------------------------------------------------------------------------
// แปลง Markdown เป็นข้อความธรรมดา
// ---------------------------------------------------------------------------
// ข้อความแบบ text ของ LINE Messaging API ไม่รองรับ Markdown
// แบบจำลองภาษามักตอบด้วย **ตัวหนา** หรือ ### หัวข้อ ตามนิสัยที่ถูกฝึกมา
// ซึ่งผู้ใช้จะเห็นเครื่องหมายเหล่านั้นเป็นตัวอักษรจริง เช่น "ภาษี **2,050 บาท**"
// ทำให้อ่านยากและดูไม่น่าเชื่อถือ จึงต้องแปลงเป็นข้อความธรรมดาก่อนส่ง
function toPlainText(text) {
  return String(text)
    // ตาราง Markdown อ่านไม่รู้เรื่องบนมือถือ
    // ต้องลบ "เส้นคั่นหัวตาราง" ก่อน มิฉะนั้นจะถูกแปลงเป็นข้อมูลแถวหนึ่ง
    .replace(/^\s*\|?[\s:|-]*\|[\s:|-]*$/gm, ' ')
    .replace(/^\s*\|(.+)\|\s*$/gm, (_, row) =>
      row.split('|').map((c) => c.trim()).filter(Boolean).join('  ')
    )
    .replace(/^ \n?/gm, '')                   // ลบบรรทัดเส้นคั่นที่ทำเครื่องหมายไว้
    .replace(/```[a-z]*\n?/gi, '')                 // รั้วโค้ด
    .replace(/^#{1,6}\s*/gm, '')                   // หัวข้อ # ## ###
    .replace(/\*\*\*(.+?)\*\*\*/g, '$1')           // ตัวหนาเอียง
    .replace(/\*\*(.+?)\*\*/g, '$1')               // ตัวหนา
    .replace(/(^|[\s(])\*(?!\s)([^*\n]+?)\*(?=[\s).,!?]|$)/g, '$1$2') // ตัวเอียง
    .replace(/(^|[\s(])_(?!\s)([^_\n]+?)_(?=[\s).,!?]|$)/g, '$1$2')   // ตัวเอียงแบบขีดล่าง
    .replace(/`([^`\n]+)`/g, '$1')                 // โค้ดในบรรทัด
    .replace(/\[([^\]]+)\]\((https?:\/\/[^)]+)\)/g, '$1 ($2)') // ลิงก์
    .replace(/^\s*[-*+]\s+/gm, '• ')               // หัวข้อย่อย
    .replace(/^\s*(\d+)\.\s+/gm, '$1. ')           // รายการมีลำดับ
    .replace(/[ \t]+$/gm, '')                      // ช่องว่างท้ายบรรทัด
    .replace(/\n{3,}/g, '\n\n')                    // บรรทัดว่างซ้อนกัน
    .trim();
}

answer = toPlainText(answer);

// ---------------------------------------------------------------------------
// บังคับคำลงท้ายให้ตรงกับบุคลิกของบอท
// ---------------------------------------------------------------------------
// บอทชื่อ "คุณภาษี" เป็นผู้หญิง ลงท้ายว่า ค่ะ ตลอด
// คำสั่งระบบสั่งเรื่องนี้ไว้แล้ว แต่การวัดผลพบว่าแบบจำลองยังหลุดใช้ ครับ เป็นบางครั้ง
// เช่นตอบว่า "ใช่ครับ เงินเพิ่มมีเพดานสูงสุด..." หรือ "ขออภัยครับ"
//
// เป็นบทเรียนเดียวกับเรื่องการเรียกเครื่องมือและคำเตือน
// สิ่งที่ต้องรับประกันได้ทุกครั้ง ต้องบังคับด้วยกฎ ไม่ใช่ขอความร่วมมือจากแบบจำลอง
// เรื่องนี้แก้ด้วยโค้ดได้ตรงไปตรงมา เพราะเป็นการแทนที่คำ ไม่ต้องเข้าใจความหมาย
//
// ใช้ขอบเขตคำเพื่อไม่ให้ไปโดนคำอื่นที่มี ครับ เป็นส่วนประกอบ
answer = answer.replace(/ครับ/g, 'ค่ะ').replace(/ค่ะๆ/g, 'ค่ะ');

// ---------------------------------------------------------------------------
// คำเตือนท้ายคำตอบ (ต่อท้ายด้วยโค้ด ไม่ปล่อยให้แบบจำลองภาษาตัดสินใจเอง)
// ---------------------------------------------------------------------------
// เหตุผลเชิงออกแบบ: คำสั่งระบบสั่งให้แบบจำลองภาษาแจ้งว่าเป็นการประมาณการอยู่แล้ว
// แต่แบบจำลองอาจลืมหรือละไว้ในบางคำตอบ ซึ่งยอมรับไม่ได้เมื่อนำไปใช้งานจริง
// เพราะผู้ใช้อาจยึดตัวเลขไปยื่นภาษีแล้วเกิดความเสียหาย
// จึงบังคับต่อท้ายด้วยโค้ด เพื่อให้ "ทุกคำตอบที่อยู่ในขอบเขตภาษี" มีคำเตือนแน่นอน 100%
const DISCLAIMER =
  '\n\n— ข้อมูลนี้เป็นการประมาณการเบื้องต้นเพื่อการศึกษา ' +
  'โปรดตรวจสอบกับกรมสรรพากร สายด่วน 1161 หรือ rd.go.th ก่อนยื่นจริง';

const inScopeCategories = [
  'คำนวณภาษี',
  'บทลงโทษ',
  'สิทธิ์ลดหย่อน',
  'กำหนดยื่นภาษี',
  'กฎหมายภาษี',
];
const category = $('Build Context').first().json.questionCategory;

// ไม่ต่อคำเตือนกับข้อความแจ้งข้อผิดพลาด เพราะไม่มีเนื้อหาภาษีให้ต้องเตือน
const isErrorMessage = answer === FALLBACK || looksLikeRawToolCall;
const needsDisclaimer = !isErrorMessage && inScopeCategories.indexOf(category) >= 0;

// ---------------------------------------------------------------------------
// บังคับความยาวคำตอบด้วยโค้ด
// ---------------------------------------------------------------------------
// เหตุผล: คำสั่งระบบกำหนดความยาวไว้แล้ว แต่การวัดผลพบว่าแบบจำลองไม่ทำตาม
// และ LINE จะพับข้อความยาวไว้หลังปุ่ม "ดูเพิ่มเติม" ซึ่งผู้ใช้ส่วนใหญ่ไม่กด
// บทเรียนเดียวกับเรื่องการเรียกเครื่องมือ คือสิ่งที่ต้องรับประกันได้
// ต้องบังคับด้วยกฎ ไม่ใช่ขอความร่วมมือจากแบบจำลอง
//
// ตัดที่ขอบบรรทัด ไม่ตัดกลางคำหรือกลางประโยค เพราะข้อความที่ขาดกลางคัน
// อ่านไม่รู้เรื่องและทำให้ระบบดูไม่น่าเชื่อถือ
//
// เคยตั้งไว้ที่ 450 แต่พบจากการทดสอบจริงว่าคำตอบเรื่องคำนวณภาษีถูกตัด
// ก่อนถึงบรรทัดที่บอกจำนวนภาษี ซึ่งเป็นข้อมูลสำคัญที่สุดที่ผู้ใช้ต้องการ
// จึงขยายเป็น 700 เพื่อให้พอสำหรับการแจกแจงขั้นตอนการคำนวณครบถ้วน
//
// ต่อมาแยกเกณฑ์เป็นสองค่าตามประเภทคำถาม ตามความเห็นของอาจารย์ที่ปรึกษา
// ว่าคำตอบประเภทอธิบายยาวเกินกว่าที่คนทั่วไปจะอ่านจบ
//
//   คำถามคำนวณ 700 ตัวอักษร  ต้องแจกแจงขั้นตอนให้ผู้ใช้ตรวจทานตามได้
//                            ถ้าตัดสั้นกว่านี้จะขาดบรรทัดที่บอกจำนวนภาษี
//   คำถามอธิบาย 420 ตัวอักษร  ราวหกถึงเจ็ดบรรทัดบนจอมือถือ
//                            พอดีกับที่ LINE แสดงได้โดยไม่ต้องกดดูเพิ่มเติม
//
// เดิมตั้งไว้ที่ 320 แต่การวัดผลพบว่าแคบเกินไป คำตอบถูกบีบจนตัดตัวเลขและเงื่อนไข
// ที่จำเป็นทิ้ง เช่นถาม SSF ลดหย่อนได้เท่าไร ตอบ 200,000 บาทถูกต้อง
// แต่ตัดเงื่อนไขไม่เกิน 30 เปอร์เซ็นต์ของเงินได้ทิ้ง ซึ่งทำให้ผู้ใช้เข้าใจผิด
// จึงขยายเป็น 420 ตัวอักษร ยังสั้นกว่าเดิมที่ 700 อยู่มาก และยังไม่ต้องกดดูเพิ่มเติม
const CALC_SOFT_LIMIT = 700;
const EXPLAIN_SOFT_LIMIT = 420;
const isCalcAnswer = ["คำนวณภาษี", "บทลงโทษ"].indexOf(category) >= 0;
const SOFT_LIMIT = isCalcAnswer ? CALC_SOFT_LIMIT : EXPLAIN_SOFT_LIMIT;
const MORE_HINT = '\n\nอยากรู้รายละเอียดเพิ่ม ถามต่อได้เลยค่ะ';

function trimAtLineBoundary(text, limit) {
  if (text.length <= limit) return { text: text, trimmed: false };
  const lines = text.split('\n');
  let out = '';
  for (const line of lines) {
    const next = out ? out + '\n' + line : line;
    if (next.length > limit) break;
    out = next;
  }
  // ถ้าบรรทัดแรกยาวเกินขีดจำกัดอยู่แล้ว ให้ถอยไปตัดที่ช่องว่างคำสุดท้ายแทน
  if (!out) {
    const cut = text.lastIndexOf(' ', limit);
    out = text.substring(0, cut > limit * 0.6 ? cut : limit);
  }
  return { text: out.trimEnd(), trimmed: true };
}

const trimResult = trimAtLineBoundary(answer, SOFT_LIMIT);
answer = trimResult.text;
if (trimResult.trimmed) answer = answer + MORE_HINT;

// กันเหนียวอีกชั้นตามข้อจำกัดจริงของ LINE เผื่อกรณีที่คาดไม่ถึง
const budget = needsDisclaimer ? MAX_LENGTH - DISCLAIMER.length : MAX_LENGTH;
if (answer.length > budget) {
  answer = answer.substring(0, budget - 3) + '...';
}
if (needsDisclaimer) {
  answer = answer + DISCLAIMER;
}

return [
  {
    json: {
      // ส่วนที่ส่งให้ LINE API (ต้องมีเฉพาะฟิลด์ที่ LINE รู้จักเท่านั้น)
      linePayload: {
        replyToken: $('Extract LINE Data').first().json.replyToken,
        messages: [{ type: 'text', text: answer }],
      },
      // ส่วนที่บันทึกลงฐานข้อมูลเพื่อนำไปวิเคราะห์ผล
      userDbId: $('Upsert User').first().json.id,
      userMessage: $('Extract LINE Data').first().json.userMessage,
      answer,
      responseTimeMs,
      matchedKnowledge: $('Build Context').first().json.matchedKnowledge,
      knowledgeHits: $('Build Context').first().json.knowledgeHits,
      questionCategory: $('Build Context').first().json.questionCategory,
      // อ่านชื่อแบบจำลองจากตัวแปร ACTIVE_MODEL_NAME ในไฟล์ .env
      // ต้องอัปเดตค่านี้ทุกครั้งที่สลับแบบจำลอง แล้วรัน docker compose restart n8n
      // ถ้าไม่ตั้งค่าจะบันทึกเป็น unknown ซึ่งดีกว่าบันทึกชื่อผิดแล้วทำให้ผลวิเคราะห์คลาดเคลื่อน
      modelName: $env.ACTIVE_MODEL_NAME || 'unknown',
    },
  },
];
